@page "/recipes/{CuisineId:int}"
@using sv_02a55dbcb0844325b63b0346a894de45.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@_sort">Italian</a> |
    <a href="/recipes/2?sort=@_sort">Indian</a> |
    <a href="/recipes/3?sort=@_sort">Japanese</a>
</nav>

<div style="margin-top: 0.5rem;">
    <label>
        Sort:
        <select @bind="SelectedSort" @bind:after="OnSortChanged">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert" style="margin-top: 1rem;">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div style="margin-top: 1rem;">
        <p><em>Loading recipes…</em></p>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div style="margin-top: 0.5rem;">
            <small><em>Refreshing…</em></small>
        </div>
    }

    <ul style="margin-top: 1rem;">
        @foreach (var recipe in GetSortedRecipes())
        {
            <li>
                <strong>@recipe.Title</strong> — @recipe.Description
                <br />
                <small>Prep time: @recipe.PrepTimeMinutes min</small>
            </li>
        }
    </ul>
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private string SelectedSort { get; set; } = "newest";

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private string _sort = "newest";

    private CancellationTokenSource? _cts;

    protected override void OnParametersSet()
    {
        var newSort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? "popular"
            : "newest";

        _sort = newSort;
        SelectedSort = newSort;

        if (CuisineId != _loadedCuisineId || (_recipes is null && _error is null))
        {
            _ = LoadRecipesAsync(CuisineId);
        }
    }

    private async Task LoadRecipesAsync(int cuisineId)
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;
        StateHasChanged();

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, token);
            token.ThrowIfCancellationRequested();

            _recipes = results;
            _loadedCuisineId = cuisineId;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was superseded or component disposed — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _error = "Something went wrong loading recipes. Please try again.";
        }

        StateHasChanged();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new();

        return _sort == "popular"
            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private void OnSortChanged()
    {
        _sort = SelectedSort;
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={_sort}");
    }

    private async Task Retry()
    {
        await LoadRecipesAsync(CuisineId);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

